SELECT p21_balances_view.year_for_period, p21_balances_view.period, p21_balances_view.period_balance, p21_balances_view.cumulative_balance, p21_balances_view.date_last_modified, p21_balances_view.last_maintained_by, p21_balances_view.date_created, p21_balances_view.encumbered_balance, p21_balances_view.encumbered_this_period, p21_balances_view.foreign_period_balance, p21_balances_view.foreign_cumulative_balance, p21_balances_view.account_no, chart_of_accts.account_desc, p21_balances_view.budget_1, p21_balances_view.budget_2, p21_balances_view.budget_3, p21_balances_view.cumulative_budget_1, p21_balances_view.cumulative_budget_2, p21_balances_view.cumulative_budget_3 
FROM p21_bal_view_derived_home_amts AS p21_balances_view  
INNER JOIN chart_of_accts 
ON (chart_of_accts.account_no = p21_balances_view.account_no AND chart_of_accts.company_no = '1') AND chart_of_accts.delete_flag = 'N' 
WHERE (p21_balances_view.company_no = '1' ) AND (p21_balances_view.account_no between '0' AND 'ZZZZZZZZZZZ') AND  ( ('N' = 'Y')  OR ((p21_balances_view.account_no LIKE '___________' ) AND  (p21_balances_view.year_for_period * 1000 + p21_balances_view.period BETWEEN 2022001 AND 2022001))) AND  ( (p21_balances_view.currency_id = 0) OR ('Y' = 'Y') )